function solve(num1, num2) {
  const n = Math.max(num1.length, num2.length);
  const raw = new Array(n + 2).fill(0);
  for (let i = 0; i < num1.length; i++) raw[i] += num1.charCodeAt(num1.length - 1 - i) - 48;
  for (let i = 0; i < num2.length; i++) raw[i] += num2.charCodeAt(num2.length - 1 - i) - 48;
  let settled = false;
  while (!settled) {
    settled = true;
    for (let i = 0; i < raw.length - 1; i++) {
      if (raw[i] >= 10) {
        raw[i] -= 10;
        raw[i + 1] += 1;
        settled = false;
        break;
      }
    }
  }
  const digits = raw.reverse().join('');
  const trimmed = digits.replace(/^0+(?=[0-9])/, '');
  return trimmed;
}

function solve(num1, num2) {
  let i = num1.length - 1;
  let j = num2.length - 1;
  let carry = 0;
  const out = [];
  while (i >= 0 || j >= 0 || carry > 0) {
    let total = carry;
    if (i >= 0) total += num1.charCodeAt(i--) - 48;
    if (j >= 0) total += num2.charCodeAt(j--) - 48;
    out.push(total % 10);
    carry = Math.floor(total / 10);
  }
  return out.reverse().join('').replace(/^0+(?=[0-9])/, '');
}
